  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'What is energy security?', 'Access to reliable, affordable and sufficient energy.', 1),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'What is energy insecurity?', 'When energy supply is unreliable, too expensive or insufficient.', 2),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'What is an energy surplus?', 'When a country produces more energy than it uses, e.g. Saudi Arabia or Norway.', 3),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'What is an energy deficit?', 'When a country uses more energy than it produces, e.g. Japan or the UK.', 4),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Where are most oil reserves?', 'The Middle East holds around half of proven oil reserves.', 5),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give two reasons for rising energy consumption.', 'Economic development and population growth (also technology and rising living standards).', 6),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Name four factors affecting energy supply.', 'Physical factors, cost of exploitation, technology and politics.', 7),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'How did politics affect energy in 2022?', 'Russia''s invasion of Ukraine caused European gas prices to soar.', 8),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give two impacts of energy insecurity.', 'Exploitation of sensitive areas (Arctic, tar sands) and reduced industrial output.', 9),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'What is load-shedding?', 'Planned power cuts, e.g. in South Africa, which reduce industrial output.', 10),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give an advantage and disadvantage of wind power.', 'Low carbon and cheap, but intermittent.', 11),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give an advantage and disadvantage of solar power.', 'Cheap and works in remote areas, but only generates in daylight.', 12),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give an advantage and disadvantage of HEP.', 'Reliable and controllable, but dams flood valleys and displace people.', 13),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give an advantage and disadvantage of geothermal energy.', 'Reliable and low carbon, but only possible in tectonically active areas.', 14),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give an advantage and disadvantage of nuclear power.', 'Reliable and low carbon, but expensive with radioactive waste.', 15),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give an advantage and disadvantage of fossil fuels.', 'Reliable with existing infrastructure, but finite and the main cause of climate change.', 16),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'What is fracking?', 'Pumping water, sand and chemicals into shale rock at high pressure to release gas.', 17),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give two advantages of fracking.', 'Domestic gas supply improves energy security; gas emits less CO₂ than coal.', 18),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give two disadvantages of fracking.', 'Earth tremors and risk of groundwater pollution.', 19),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Why is gas called a "bridge" fuel?', 'It emits about half the CO₂ of coal while renewables expand.', 20),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'What is a carbon footprint?', 'The total greenhouse gases caused by a person, product or activity.', 21),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give two ways to reduce your carbon footprint.', 'Insulate your home and use public transport, cycling or walking.', 22),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'How can homes be designed to save energy?', 'Insulation, triple glazing, solar panels, heat pumps and passive solar design.', 23),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'How can transport use less energy?', 'Electric vehicles, public transport, cycle lanes and congestion charges.', 24),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'How do smart meters help?', 'They show real-time energy use so people waste less.', 25),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Where is the Chambamontera micro-hydro scheme?', 'A remote village in the Andes of northern Peru.', 26),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Who helped build the Chambamontera scheme?', 'The charity Practical Action, with the local community.', 27),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'How does a micro-hydro scheme work?', 'Stream water flows through a pipe to turn a small turbine and generate electricity.', 28),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Give two benefits of the Chambamontera scheme.', 'Lighting for study after dark, and less smoke from kerosene and firewood.', 29),
  ('Geography', 'AQA', 'gcse', '2.7', 'Energy', 'Why is Chambamontera''s scheme sustainable?', 'Renewable, no large dam, low-cost and maintained by trained local people.', 30),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'How long is AQA GCSE Geography Paper 3?', '1 hour 15 minutes, 76 marks including 6 for SPaG.', 1),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What are the two sections of Paper 3?', 'Section A: issue evaluation; Section B: fieldwork.', 2),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'When is the pre-release booklet issued?', '12 weeks before the exam.', 3),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is the final issue evaluation question worth?', '9 marks, plus 3 marks for SPaG.', 4),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'Is there a right answer in the issue evaluation decision?', 'No — marks come from justifying your choice using evidence from the resources.', 5),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'How many fieldwork enquiries must you complete?', 'Two: one physical and one human, in contrasting environments.', 6),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What are the six stages of an enquiry?', 'Question, data collection, processing and presenting, analysing and explaining, conclusions, evaluation.', 7),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is a hypothesis?', 'A statement that can be tested and proved or disproved by an investigation.', 8),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is primary data?', 'Data you collect yourself during fieldwork.', 9),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is secondary data?', 'Data collected by others, e.g. census data, maps or Environment Agency records.', 10),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is random sampling?', 'Every item has an equal chance of being selected.', 11),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is systematic sampling?', 'Taking samples at regular intervals, e.g. every 10 m along a transect.', 12),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is stratified sampling?', 'Sampling sub-groups in proportion to their size in the population.', 13),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What does the Bradshaw model predict?', 'Width, depth, velocity and discharge increase downstream; gradient and particle size decrease.', 14),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'How do you measure river velocity simply?', 'Time a float over a set distance (e.g. 10 m) and repeat three times.', 15),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'Name two risks in river fieldwork.', 'Slipping or drowning, and waterborne disease such as Weil''s disease.', 16),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is an environmental quality survey?', 'A survey scoring places on features such as litter, graffiti and green space.', 17),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'Why are environmental quality surveys unreliable?', 'Scoring is subjective and varies between people.', 18),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'Which graph shows a relationship between two variables?', 'A scatter graph with a line of best fit.', 19),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is a choropleth map?', 'A map shaded in different intensities to show data values for areas.', 20),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is the mean?', 'The total of all values divided by the number of values.', 21),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is the median?', 'The middle value when data is placed in order.', 22),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is the mode?', 'The value that occurs most often.', 23),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is the range?', 'The difference between the highest and lowest values.', 24),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is the interquartile range?', 'The spread of the middle 50% of data — upper quartile minus lower quartile.', 25),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What is an anomaly?', 'A result that does not fit the general pattern.', 26),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What does correlation not prove?', 'Causation — another factor may cause both variables to change.', 27),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What should a fieldwork conclusion do?', 'Answer the original question using evidence from the results.', 28),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'What does fieldwork evaluation involve?', 'Identifying problems with methods and data, their effects, and improvements.', 29),
  ('Geography', 'AQA', 'gcse', '3.1', 'Issue Evaluation and Fieldwork', 'How can fieldwork reliability be improved?', 'More sites, larger samples, repeat visits and better equipment.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Geography' AND exam_board = 'AQA' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
